(()=>{'use strict';const P=window.DEMO_PAGE,A=window.LEGACY_CELL_HINT_ASSETS,indices=A?.profiles[P?.id];if(!indices)return;let tip,anchor,timer,leaveTimer;
function close(){clearTimeout(timer);clearTimeout(leaveTimer);timer=leaveTimer=null;tip?.remove();tip=null;anchor?.removeAttribute('aria-describedby');anchor=null;}
function show(cell){close();if(!cell.isConnected||!cell.textContent.trim())return;anchor=cell;const t=document.createElement('template');t.innerHTML=A.html;tip=t.content.firstElementChild;tip.style.cssText='position:fixed;inset:auto;z-index:1050;pointer-events:auto;box-sizing:border-box';const text=tip.querySelector(A.textSelector);text.textContent=cell.textContent.trim();for(const[k,v]of Object.entries(A.font||{}))text.style.setProperty(k,v);const role=tip.matches('[role=tooltip]')?tip:tip.querySelector('[role=tooltip]');if(role){role.id='legacy-cell-full-value';cell.setAttribute('aria-describedby',role.id);}document.body.append(tip);const r=(cell.querySelector('.tooltip___Hn4K')||cell).getBoundingClientRect(),b=tip.getBoundingClientRect(),gap=A.gap||12;tip.style.left=Math.max(4,Math.min(innerWidth-b.width-4,Math.round(r.x+r.width/2-b.width/2)))+'px';const bottom=r.top-b.height-gap<0;tip.style.top=Math.round(bottom?r.bottom+gap:r.top-b.height-gap)+'px';tip.classList.toggle(A.topClass||'kodo-new-popover-placement-top',!bottom);tip.classList.toggle(A.bottomClass||'kodo-new-popover-placement-bottom',bottom);const arrow=tip.querySelector(A.arrowSelector);if(arrow)arrow.style.cssText='position:absolute;left:50%;'+(bottom?'top:0':'bottom:0');}
function wire(){for(const table of document.querySelectorAll('table'))for(const row of table.querySelectorAll('tbody tr:not(.ant-table-measure-row):not(.kodo-new-table-measure-row)'))for(const index of indices){const cell=row.children[index];if(!cell||!cell.querySelector('.tooltip___Hn4K'))continue;cell.dataset.legacyFullValue='1';}}
wire();document.addEventListener('pointerover',e=>{const cell=e.target.closest('[data-legacy-full-value]');if(cell){clearTimeout(leaveTimer);if(anchor===cell||timer)return;timer=setTimeout(()=>show(cell),100);}else if(tip?.contains(e.target))clearTimeout(leaveTimer);else{clearTimeout(timer);timer=null;clearTimeout(leaveTimer);leaveTimer=setTimeout(close,100);}},true);
window.addEventListener('keydown',e=>{if(e.key==='Escape')close();},true);window.addEventListener('pointerdown',e=>{if(!tip?.contains(e.target))close();},true);window.addEventListener('scroll',e=>{if(!(e.target instanceof Node)||!tip?.contains(e.target))close();},true);window.addEventListener('resize',close);document.documentElement.dataset.legacyCellHintsReady='1';})();
